//! Embedding columns kept current (PLAN.md §M14.22 E4b).
//!
//! `v vector(384) GENERATED BY EMBEDDING (title || ' ' || body) USING m`:
//! a write that may change a row's text — an insert, an update of a
//! column the expression reads, a key moved — puts a *job* on the queue
//! in the same transaction, one key a row and column (`00 17 <table id>
//! <column u16> <primary key>`), so five updates while one is pending are
//! one job and the newest text wins.  The vector a row has stays until
//! the new one is written: a query sees each row's vector as it is
//! (`embedding.pending = include`, the default), leaves out the rows with
//! a job (`skip`), or first waits for the jobs (`wait`).
//!
//! A *round* ([`work`]) takes the due jobs, at most [`ROUND_TEXTS`] of
//! them, reads their rows' texts at one snapshot, calls each column's
//! model with them in batches (the model's), then writes the vectors in
//! a transaction that reads each job and its row again: a job changed
//! since (its row written again) is left for the next round, a row whose
//! text is the one embedded gets its vector and loses its job.  A
//! transaction that conflicts with a writer leaves its jobs for the next
//! round.  Failures:
//!
//! - one that may pass (`58030` — a provider throttling, down, out of
//!   reach — or a conflict): tried again after an exponential backoff
//!   with full jitter (Brooker, "Exponential Backoff and Jitter", 2015:
//!   a draw from 0 to the 1 s × 2ⁿ cap, at most five minutes), or after
//!   the provider's `Retry-After` when it gave one;
//! - one that will not (a refused key, a text the model refuses): the job
//!   is marked failed at once, its error kept, and tried again in an hour
//!   or when its row's text changes — a batch refused as a whole is tried
//!   a text at a time, so one bad text fails alone;
//! - five failures in a row that may pass open the model's *circuit*: no
//!   calls to it for 30 s, doubling to five minutes while it stays down,
//!   so an outage costs a call a period, not one a job.
//!
//! Who runs rounds: the engine's sessions, after their statements
//! ([`after_statement`]: the embedded library keeps its columns current
//! with no thread of its own, as an HNSW index's upkeep is paid), unless
//! a background worker ([`serve`], the server's) serves the database.
//! Everything runs on the database's clock and random source, so the
//! simulator drives outages and crashes; the queue is in the database,
//! so a crash loses no job.

use std::collections::{BTreeMap, HashMap};
use std::ops::Bound;
use std::sync::{Arc, Condvar, Mutex, OnceLock};
use std::time::Duration;

use nucleus_kv::{Kv, KvTxn, TxnOptions};

use crate::binder::Binder;
use crate::catalog::{self, INDEX_PREFIX_LEN, Table};
use crate::encoding::{Reader, Writer as Bytes};
use crate::error::{Error, Result};
use crate::expr::{Ctx, Env, Expr};
use crate::ext::{
    Arg, ArgInfo, CallContext, FnRef, Registry, Returns, ScalarFunction, Signature, Volatility,
};
use crate::types::{DataType, Row, Value};

const QUEUE: [u8; 2] = [0x00, 0x17];
/// The vectors of a column's next model, made beside it (§M14.22 E5):
/// `00 18 <table id> <column u16> <pk>` → its components (f32, little
/// endian; none: the row's text is NULL).
const SHADOW: [u8; 2] = [0x00, 0x18];
/// The mark in a job's column of a job for the column's next model.
pub(crate) const NEXT: usize = 0x8000;
const ENTRY_VERSION: u8 = 1;

/// The most texts a round takes, of all columns.
pub const ROUND_TEXTS: usize = 256;
/// A retry's wait: up to this, doubled each attempt …
const BACKOFF_BASE_MS: i64 = 1_000;
/// … to at most this.
const BACKOFF_CAP_MS: i64 = 5 * 60 * 1_000;
/// A job failed for good is tried again after this.
const FAILED_RETRY_MS: i64 = 60 * 60 * 1_000;
/// Failures that may pass, in a row, that open a model's circuit.
const CIRCUIT_FAILURES: u32 = 5;
/// How long a circuit first stays open; doubled each time it opens again
/// without a success between, up to [`BACKOFF_CAP_MS`].
const CIRCUIT_OPEN_MS: i64 = 30_000;

/// The setting choosing how queries treat rows whose vectors are pending.
pub const PENDING_SETTING: &str = "embedding.pending";

// ------------------------------------------------------------------ jobs

/// A job, as the queue keeps it.
#[derive(Clone, Debug, PartialEq)]
struct Entry {
    /// When it was put (µs since 2000-01-01 UTC; the statement's time).
    enqueued: i64,
    /// Failed calls so far.
    attempts: u32,
    /// Not before (µs; 0: at once).
    next_at: i64,
    /// Failed for good (until its retry or its row's next change).
    failed: bool,
    /// The last error.
    error: Option<String>,
}

impl Entry {
    fn encode(&self) -> Vec<u8> {
        let mut w = Bytes::default();
        w.u8(ENTRY_VERSION)
            .u64(self.enqueued as u64)
            .u32(self.attempts)
            .u64(self.next_at as u64)
            .u8(u8::from(self.failed))
            .opt_str(self.error.as_deref());
        w.0
    }

    fn decode(b: &[u8]) -> Result<Self> {
        let mut r = Reader::new(b);
        if r.u8()? != ENTRY_VERSION {
            return Err(Error::internal("unknown embedding job version"));
        }
        Ok(Entry {
            enqueued: r.u64()? as i64,
            attempts: r.u32()?,
            next_at: r.u64()? as i64,
            failed: r.u8()? == 1,
            error: r.opt_str()?,
        })
    }
}

fn table_prefix(table_id: u32) -> Vec<u8> {
    let mut k = QUEUE.to_vec();
    k.extend_from_slice(&table_id.to_be_bytes());
    k
}

fn job_key(table_id: u32, column: usize, pk: &[u8]) -> Vec<u8> {
    let mut k = table_prefix(table_id);
    k.extend_from_slice(&(column as u16).to_be_bytes());
    k.extend_from_slice(pk);
    k
}

fn shadow_prefix(table_id: u32, column: usize) -> Vec<u8> {
    let mut k = SHADOW.to_vec();
    k.extend_from_slice(&table_id.to_be_bytes());
    k.extend_from_slice(&(column as u16).to_be_bytes());
    k
}

fn shadow_key(table_id: u32, column: usize, pk: &[u8]) -> Vec<u8> {
    let mut k = shadow_prefix(table_id, column);
    k.extend_from_slice(pk);
    k
}

/// The jobs of one column (`slot`: its position, [`NEXT`] marking its
/// next model's).
fn slot_prefix(table_id: u32, slot: usize) -> Vec<u8> {
    let mut k = table_prefix(table_id);
    k.extend_from_slice(&(slot as u16).to_be_bytes());
    k
}

/// A job key's table id, column and primary key.
fn parse_key(k: &[u8]) -> Option<(u32, usize, &[u8])> {
    let rest = k.strip_prefix(&QUEUE[..])?;
    if rest.len() < 6 {
        return None;
    }
    let id = u32::from_be_bytes(rest[..4].try_into().ok()?);
    let col = u16::from_be_bytes(rest[4..6].try_into().ok()?);
    Some((id, col as usize, &rest[6..]))
}

/// The embedding columns of `t`, by position.
pub(crate) fn columns_of(t: &Table) -> impl Iterator<Item = usize> + '_ {
    t.columns.iter().enumerate().filter_map(|(i, c)| {
        matches!(c.generated, Some(crate::ast::Generated::Embedding { .. })).then_some(i)
    })
}

/// Whether column `c` of `t` is moving to another model.
pub(crate) fn moving(t: &Table, c: usize) -> bool {
    t.columns[c]
        .generated
        .as_ref()
        .and_then(|g| g.next_model())
        .is_some()
}

/// The row under primary key `pk` has a new text for column `c`: a job
/// for its vector, and one for its next model's while it moves.
pub(crate) fn enqueue_row(txn: &mut dyn KvTxn, t: &Table, c: usize, pk: &[u8]) -> Result<()> {
    enqueue(txn, t.id, c, pk)?;
    if moving(t, c) {
        enqueue(txn, t.id, c | NEXT, pk)?;
    }
    Ok(())
}

/// Puts a job for column `column` of the row under primary key `pk`
/// (anew: a job there is replaced, its failures forgotten).
fn enqueue(txn: &mut dyn KvTxn, table_id: u32, column: usize, pk: &[u8]) -> Result<()> {
    let e = Entry {
        enqueued: crate::datetime::now().unwrap_or(0),
        attempts: 0,
        next_at: 0,
        failed: false,
        error: None,
    };
    txn.put(&job_key(table_id, column, pk), &e.encode())?;
    note(txn.instance());
    Ok(())
}

/// A row's key changed from `from` to `to`: its jobs, and the vector its
/// next model made, follow it.
pub(crate) fn moved(
    txn: &mut dyn KvTxn,
    t: &Table,
    c: usize,
    from: &[u8],
    to: &[u8],
) -> Result<()> {
    let mut keys = vec![(job_key(t.id, c, from), job_key(t.id, c, to))];
    if moving(t, c) {
        keys.push((job_key(t.id, c | NEXT, from), job_key(t.id, c | NEXT, to)));
        keys.push((shadow_key(t.id, c, from), shadow_key(t.id, c, to)));
    }
    for (old, new) in keys {
        if let Some(v) = txn.get(&old)? {
            txn.delete(&old)?;
            txn.put(&new, &v)?;
        }
    }
    Ok(())
}

/// A row deleted: its jobs go (and its next model's vector).
pub(crate) fn dequeue(txn: &mut dyn KvTxn, t: &Table, c: usize, pk: &[u8]) -> Result<()> {
    txn.delete(&job_key(t.id, c, pk))?;
    if moving(t, c) {
        txn.delete(&job_key(t.id, c | NEXT, pk))?;
        txn.delete(&shadow_key(t.id, c, pk))?;
    }
    Ok(())
}

fn delete_prefix(txn: &mut dyn KvTxn, p: &[u8]) -> Result<()> {
    let end = nucleus_kv::prefix_end(p).expect("a prefix");
    catalog::delete_range(txn, p, Some(&end)).map(|_| ())
}

/// A table dropped: its jobs go, and its next models' vectors.
pub(crate) fn forget_table(txn: &mut dyn KvTxn, table_id: u32) -> Result<()> {
    delete_prefix(txn, &table_prefix(table_id))?;
    let mut p = SHADOW.to_vec();
    p.extend_from_slice(&table_id.to_be_bytes());
    delete_prefix(txn, &p)
}

/// Every row of `t` gets a job for `column` (a column just added).
pub(crate) fn enqueue_all(
    txn: &mut dyn KvTxn,
    reg: &Registry,
    t: &Table,
    column: usize,
) -> Result<()> {
    let keys: Vec<Vec<u8>> = {
        let ctx = Ctx::new(&*txn, reg, &[]);
        crate::exec::matching(t, &crate::plan::Access::Full, None, &ctx)?
            .map(|r| r.map(|(k, _)| k[INDEX_PREFIX_LEN..].to_vec()))
            .collect::<Result<_>>()?
    };
    for pk in keys {
        enqueue(txn, t.id, column, &pk)?;
    }
    note(txn.instance());
    Ok(())
}

/// `ALTER TABLE t ALTER COLUMN v SET MODEL m` (§M14.22 E5): the vectors of
/// model `m` made beside the column's, a job a row, by the rounds; when
/// the last is made, one transaction makes them the column's (its
/// dimensions `m`'s, its indexes built again) — until then queries read
/// the old model's.  The column's own model again: a move under way is
/// given up.  Another: it starts over.
pub(crate) fn set_model(
    txn: &mut dyn KvTxn,
    reg: &Registry,
    table: &str,
    column: &str,
    model: &str,
) -> Result<()> {
    let mut t = catalog::table(&*txn, table)?;
    let c = t.column(column).ok_or_else(|| {
        Error::undefined_column(format!(
            "column \"{column}\" of relation \"{table}\" does not exist"
        ))
    })?;
    if crate::models::get(&*txn, model)?.is_none() {
        return Err(Error::undefined_object(format!(
            "model \"{model}\" does not exist"
        )));
    }
    crate::privileges::Checker::new().require(
        &*txn,
        crate::privileges::Kind::Model,
        model,
        crate::privileges::USAGE,
        None,
    )?;
    let Some(crate::ast::Generated::Embedding {
        model: current,
        next,
        ..
    }) = &mut t.columns[c].generated
    else {
        return Err(Error::wrong_object_type(format!(
            "column \"{column}\" is not an embedding column (GENERATED BY EMBEDDING)"
        )));
    };
    // What a move under way made so far goes.
    delete_prefix(txn, &slot_prefix(t.id, c | NEXT))?;
    delete_prefix(txn, &shadow_prefix(t.id, c))?;
    *next = (current.as_str() != model).then(|| model.to_string());
    let starts = next.is_some();
    catalog::update_table(txn, &t)?;
    if starts {
        enqueue_all(txn, reg, &t, c | NEXT)?;
    }
    Ok(())
}

// ------------------------------------------------------------- the DDL

/// Settles an embedding column of a table being defined: its model
/// exists and the maker may use it, its type is `vector` of the model's
/// dimensions (`vector` alone takes them), it may be NULL, and the table
/// has a primary key (by which a query tells a row's job).
pub(crate) fn settle(txn: &dyn KvTxn, t: &mut Table) -> Result<()> {
    for c in columns_of(t).collect::<Vec<_>>() {
        let model_name = t.columns[c]
            .generated
            .as_ref()
            .and_then(|g| g.model())
            .expect("an embedding column")
            .to_string();
        let name = t.columns[c].name.clone();
        let m = crate::models::get(txn, &model_name)?.ok_or_else(|| {
            Error::undefined_object(format!("model \"{model_name}\" does not exist"))
        })?;
        crate::privileges::Checker::new().require(
            txn,
            crate::privileges::Kind::Model,
            &model_name,
            crate::privileges::USAGE,
            None,
        )?;
        let col = &mut t.columns[c];
        if col.ty != crate::vectors::data_type() {
            return Err(Error::type_mismatch(format!(
                "embedding column \"{name}\" is of type {}: it must be vector({})",
                col.ty, m.dimensions
            )));
        }
        match col.max_len {
            None => col.max_len = Some(m.dimensions),
            Some(n) if n == m.dimensions => {}
            Some(n) => {
                return Err(Error::type_mismatch(format!(
                    "embedding column \"{name}\" is vector({n}), but model \"{model_name}\" makes vectors of {} dimensions",
                    m.dimensions
                )));
            }
        }
        if !col.nullable {
            return Err(Error::invalid_object_definition(format!(
                "embedding column \"{name}\" cannot be NOT NULL: it is NULL until its vector is made"
            )));
        }
        if t.primary_key.is_empty() {
            return Err(Error::invalid_object_definition(format!(
                "table \"{}\" needs a primary key for embedding column \"{name}\"",
                t.name
            )));
        }
        if t.primary_key.contains(&c) {
            return Err(Error::invalid_object_definition(format!(
                "embedding column \"{name}\" cannot be in the primary key"
            )));
        }
    }
    Ok(())
}

/// The tables with an embedding column made by model `name` (it is not
/// dropped under them).
pub(crate) fn using_model(txn: &dyn KvTxn, name: &str) -> Result<Vec<String>> {
    Ok(catalog::tables(txn)?
        .into_iter()
        .filter(|t| {
            t.columns.iter().any(|c| {
                c.generated
                    .as_ref()
                    .is_some_and(|g| g.model() == Some(name) || g.next_model() == Some(name))
            })
        })
        .map(|t| t.name)
        .collect())
}

// ------------------------------------------------------- pending rows

/// Whether a row of one table — by its primary key's values — has a job:
/// the condition `embedding.pending = skip` puts on the table's scans.
struct Pending {
    name: String,
    table: Table,
    columns: Vec<usize>,
}

impl ScalarFunction for Pending {
    fn name(&self) -> &str {
        &self.name
    }

    fn arity(&self) -> std::ops::RangeInclusive<usize> {
        let n = self.table.primary_key.len();
        n..=n
    }

    fn resolve(&self, args: &[ArgInfo]) -> Result<Signature> {
        Ok(Signature {
            args: vec![Arg::Keep; args.len()],
            returns: Returns::Type(Some(DataType::Bool)),
        })
    }

    fn strict(&self) -> bool {
        false
    }

    fn volatility(&self) -> Volatility {
        Volatility::Stable
    }

    fn parallel_safe(&self) -> bool {
        true
    }

    fn call(&self, cx: &CallContext<'_>, args: &[Value]) -> Result<Value> {
        let key = catalog::row_key(&self.table, args);
        let pk = &key[INDEX_PREFIX_LEN..];
        for &c in &self.columns {
            if cx.txn().get(&job_key(self.table.id, c, pk))?.is_some() {
                return Ok(Value::Bool(true));
            }
        }
        Ok(Value::Bool(false))
    }
}

/// How queries treat rows whose vectors are pending: the session's
/// `embedding.pending`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PendingRows {
    /// Vectors as they are (the default).
    Include,
    /// Rows with a job left out.
    Skip,
    /// The statement first waits for the jobs.
    Wait,
}

impl PendingRows {
    /// The setting's value, checked.
    pub fn parse(v: &str) -> Result<Self> {
        match v.trim().trim_matches('\'').to_ascii_lowercase().as_str() {
            "include" => Ok(Self::Include),
            "skip" => Ok(Self::Skip),
            "wait" => Ok(Self::Wait),
            other => Err(Error::invalid_parameter(format!(
                "invalid value for parameter \"{PENDING_SETTING}\": \"{other}\" (include, skip or wait)"
            ))),
        }
    }

    /// The session's.
    pub fn current() -> Self {
        crate::expr::setting(PENDING_SETTING)
            .and_then(|v| Self::parse(&v).ok())
            .unwrap_or(Self::Include)
    }
}

/// For a scan of `t` under `embedding.pending = skip`: the condition its
/// rows must meet (none without embedding columns).
pub(crate) fn skip_condition(t: &Table) -> Option<Expr> {
    let columns: Vec<usize> = columns_of(t).collect();
    if columns.is_empty() || PendingRows::current() != PendingRows::Skip {
        return None;
    }
    let pending = Pending {
        name: format!("embedding_pending({})", t.name),
        table: t.clone(),
        columns,
    };
    Some(Expr::Unary(
        crate::ast::UnaryOp::Not,
        Box::new(Expr::Call(
            FnRef::new(Arc::new(pending)),
            t.primary_key.iter().map(|&c| Expr::Column(c)).collect(),
        )),
    ))
}

// -------------------------------------------------------------- rounds

/// What a round did.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Round {
    /// Vectors written.
    pub embedded: usize,
    /// Jobs done without a vector: the row gone, or its text NULL.
    pub cleared: usize,
    /// Calls that failed (their jobs tried again later).
    pub failed: usize,
    /// Due jobs left for the next round (more than a round takes).
    pub due: usize,
    /// Jobs not failed for good, before the round (a column's next
    /// model's not counted).
    pub waiting: usize,
    /// Jobs of columns' next models not failed for good, before the round.
    pub moving: usize,
    /// Columns whose next model became theirs.
    pub moved: usize,
    /// When the first job not yet due will be (µs since 2000), if any.
    pub next: Option<i64>,
    /// Another round was running for this database: nothing done.
    pub busy: bool,
}

impl Round {
    /// Whether the round did anything.
    pub fn worked(&self) -> bool {
        self.embedded + self.cleared + self.failed + self.moved > 0
    }
}

struct Job {
    key: Vec<u8>,
    pk: Vec<u8>,
    entry: Vec<u8>,
}

/// A model's circuit, per database.
#[derive(Default)]
struct Circuit {
    failures: u32,
    opened: u32,
    open_until: i64,
}

struct Driver {
    /// A background worker serves this database.
    background: bool,
    /// A job may have been put since the last round.
    maybe: bool,
    /// A round is running.
    busy: bool,
    /// When a job will be due.
    next: Option<i64>,
    circuits: HashMap<String, Circuit>,
}

impl Default for Driver {
    fn default() -> Self {
        Driver {
            background: false,
            // Jobs a process before this one left: a round finds them.
            maybe: true,
            busy: false,
            next: None,
            circuits: HashMap::new(),
        }
    }
}

fn drivers() -> &'static (Mutex<HashMap<u64, Driver>>, Condvar) {
    static D: OnceLock<(Mutex<HashMap<u64, Driver>>, Condvar)> = OnceLock::new();
    D.get_or_init(|| (Mutex::new(HashMap::new()), Condvar::new()))
}

fn with_driver<R>(instance: u64, f: impl FnOnce(&mut Driver) -> R) -> R {
    let mut d = drivers().0.lock().unwrap_or_else(|e| e.into_inner());
    f(d.entry(instance).or_default())
}

/// A job was put in database `instance`.
fn note(instance: u64) {
    with_driver(instance, |d| d.maybe = true);
    drivers().1.notify_all();
}

/// Whether an error may pass when tried again.
fn transient(e: &Error) -> bool {
    matches!(e.code, "58030" | "40001" | "57014" | "53300" | "53400")
}

/// The next wait after `attempts` failed calls: a draw from zero to the
/// capped exponential (full jitter).
fn backoff(kv: &dyn Kv, attempts: u32) -> i64 {
    let cap = BACKOFF_BASE_MS
        .saturating_mul(1i64 << attempts.saturating_sub(1).min(20))
        .min(BACKOFF_CAP_MS);
    let mut b = [0u8; 8];
    kv.random_bytes(&mut b);
    (u64::from_le_bytes(b) % (cap as u64 + 1)) as i64 * 1_000
}

/// The text column `column`'s expression gives for `row`.
fn text_of(source: &Expr, row: &Row, ctx: &Ctx) -> Result<Option<String>> {
    match source.eval(&Env {
        row,
        outer: None,
        ctx,
    })? {
        Value::Null => Ok(None),
        Value::Text(s) => Ok(Some(s.to_string())),
        other => Ok(Some(other.to_string())),
    }
}

fn bind_source(txn: &dyn KvTxn, reg: &Registry, t: &Table, column: usize) -> Result<Expr> {
    let g = t.columns[column]
        .generated
        .as_ref()
        .ok_or_else(|| Error::internal("an embedding job for a column not generated"))?;
    Ok(Binder::new(txn, reg)
        .expr(
            &crate::parser::parse_expr(g.expr())?,
            &crate::dml::table_scope(t),
        )?
        .0)
}

fn row_key(t: &Table, pk: &[u8]) -> Vec<u8> {
    let mut k = t.index_prefix(0);
    k.extend_from_slice(pk);
    k
}

/// One round of the queue of database `kv`: the due jobs (at most
/// [`ROUND_TEXTS`]), their texts embedded, their vectors written.
pub fn work(kv: &Arc<dyn Kv>, reg: &Registry) -> Result<Round> {
    let instance = kv.instance();
    if with_driver(instance, |d| std::mem::replace(&mut d.busy, true)) {
        return Ok(Round {
            busy: true,
            ..Round::default()
        });
    }
    let r = round(kv, reg);
    with_driver(instance, |d| {
        d.busy = false;
        if let Ok(r) = &r {
            d.next = r.next;
            d.maybe |= r.due > 0;
        }
    });
    r
}

fn round(kv: &Arc<dyn Kv>, reg: &Registry) -> Result<Round> {
    let instance = kv.instance();
    let now = crate::datetime::from_system(kv.wall_clock());
    let mut round = Round::default();
    let ro = kv.begin(TxnOptions::read_only())?;
    let tables: HashMap<u32, Table> = catalog::tables(&*ro)?
        .into_iter()
        .map(|t| (t.id, t))
        .collect();
    let open: HashMap<String, i64> = with_driver(instance, |d| {
        d.circuits
            .iter()
            .filter(|(_, c)| c.open_until > now)
            .map(|(m, c)| (m.clone(), c.open_until))
            .collect()
    });
    // Groups by table and slot (a column, or its next model's): the
    // columns' own jobs first, a next model's in the room they leave.
    let mut groups: BTreeMap<(u32, usize), Vec<Job>> = BTreeMap::new();
    let mut later: Vec<((u32, usize), Job)> = Vec::new();
    let mut seen_next: std::collections::HashSet<(u32, usize)> = Default::default();
    let mut taken = 0;
    let end = nucleus_kv::prefix_end(&QUEUE).expect("queue prefix");
    for e in ro.scan(Bound::Included(&QUEUE[..]), Bound::Excluded(&end[..]))? {
        let (k, v) = e?;
        let Some((table_id, slot, pk)) = parse_key(&k) else {
            continue;
        };
        let (column, next) = (slot & !NEXT, slot & NEXT != 0);
        let entry = Entry::decode(&v)?;
        if next {
            seen_next.insert((table_id, slot));
        }
        if !entry.failed {
            if next {
                round.moving += 1;
            } else {
                round.waiting += 1;
            }
        }
        let Some(model) = tables
            .get(&table_id)
            .and_then(|t| t.columns.get(column))
            .and_then(|c| c.generated.as_ref())
            .and_then(|g| if next { g.next_model() } else { g.model() })
        else {
            continue;
        };
        let due_at = entry.next_at.max(open.get(model).copied().unwrap_or(0));
        if due_at > now {
            round.next = Some(round.next.map_or(due_at, |n| n.min(due_at)));
            continue;
        }
        let job = Job {
            pk: pk.to_vec(),
            key: k,
            entry: v,
        };
        if next {
            if later.len() < ROUND_TEXTS {
                later.push(((table_id, slot), job));
            } else {
                round.due += 1;
            }
            continue;
        }
        if taken >= ROUND_TEXTS {
            round.due += 1;
            continue;
        }
        taken += 1;
        groups.entry((table_id, slot)).or_default().push(job);
    }
    for (group, job) in later {
        if taken >= ROUND_TEXTS {
            round.due += 1;
            continue;
        }
        taken += 1;
        groups.entry(group).or_default().push(job);
    }
    for (&(table_id, slot), jobs) in &groups {
        let t = &tables[&table_id];
        let column = slot & !NEXT;
        let g = t.columns[column]
            .generated
            .as_ref()
            .expect("an embedding column");
        let model = if slot & NEXT != 0 {
            g.next_model()
        } else {
            g.model()
        }
        .expect("an embedding column's model")
        .to_string();
        // The texts, at the round's snapshot.
        let texts: Vec<Option<String>> = {
            let source = bind_source(&*ro, reg, t, column)?;
            let storage = crate::storage::of(t)?;
            let ctx = Ctx::new(&*ro, reg, &[]);
            let mut labels = crate::enums::Labels::default();
            let mut texts = Vec::with_capacity(jobs.len());
            for j in jobs {
                let row = storage.get(&*ro, t, &row_key(t, &j.pk), None, &mut labels)?;
                texts.push(match row {
                    Some(r) => text_of(&source, &r, &ctx)?,
                    None => None,
                });
            }
            texts
        };
        let asked: Vec<&str> = texts.iter().flatten().map(String::as_str).collect();
        // On the database's clock: a model's rate limits read it.
        let results = crate::datetime::with_now(now, kv, || call(&*ro, &model, &asked));
        let (ok, failed) = results.iter().fold((false, false), |(o, f), r| match r {
            Ok(_) => (true, f),
            // The model's own rate limit is not the provider down.
            Err(e) => (o, f || (transient(e) && !crate::models::throttled(e))),
        });
        with_driver(instance, |d| {
            let c = d.circuits.entry(model.clone()).or_default();
            if ok {
                *c = Circuit::default();
            } else if failed {
                c.failures += 1;
                if c.failures >= CIRCUIT_FAILURES {
                    let wait = CIRCUIT_OPEN_MS
                        .saturating_mul(1i64 << c.opened.min(20))
                        .min(BACKOFF_CAP_MS);
                    c.open_until = now + wait * 1_000;
                    c.opened += 1;
                    c.failures = 0;
                }
            }
        });
        round.failed += results.iter().filter(|r| r.is_err()).count();
        write_back(kv, reg, t, slot, jobs, &texts, results, now, &mut round)?;
    }
    // A column whose next model's vectors are all made takes them.
    for t in tables.values() {
        for c in columns_of(t).filter(|&c| moving(t, c)) {
            let slot = (t.id, c | NEXT);
            if seen_next.contains(&slot) && !groups.contains_key(&slot) {
                continue; // its jobs not due yet
            }
            if swap(kv, reg, t.id, c)? {
                round.moved += 1;
            }
        }
    }
    Ok(round)
}

/// Whether a key starts with `prefix`.
fn any_under(txn: &dyn KvTxn, prefix: &[u8]) -> Result<bool> {
    let end = nucleus_kv::prefix_end(prefix).expect("a prefix");
    Ok(txn
        .scan(Bound::Included(prefix), Bound::Excluded(&end[..]))?
        .next()
        .transpose()?
        .is_some())
}

/// Column `column` of table `table_id` takes its next model's vectors,
/// when no job for them is left: its rows rewritten with them, its type
/// the model's dimensions, its indexes built again, its model the next
/// (its version one more) — one transaction, so a query reads one
/// model's vectors or the other's.  Whether it did.
fn swap(kv: &Arc<dyn Kv>, reg: &Registry, table_id: u32, column: usize) -> Result<bool> {
    let mut txn = kv.begin(TxnOptions::default())?;
    let Some(old) = catalog::tables(&*txn)?
        .into_iter()
        .find(|t| t.id == table_id)
    else {
        return Ok(false);
    };
    if !moving(&old, column) || any_under(&*txn, &slot_prefix(table_id, column | NEXT))? {
        return Ok(false);
    }
    let mut new = old.clone();
    {
        let col = &mut new.columns[column];
        let Some(crate::ast::Generated::Embedding {
            model,
            version,
            next,
            ..
        }) = &mut col.generated
        else {
            return Ok(false);
        };
        let to = next.take().expect("a column moving");
        let m = crate::models::get(&*txn, &to)?
            .ok_or_else(|| Error::undefined_object(format!("model \"{to}\" does not exist")))?;
        *model = to;
        *version += 1;
        col.max_len = Some(m.dimensions);
    }
    let shape = new.clone();
    for ix in &mut new.indexes {
        if ix.columns.contains(&column)
            && let Some(m) = crate::index_method::of(ix)?
        {
            m.define(&shape, ix)?;
        }
    }
    let rows = {
        let ctx = Ctx::new(&*txn, reg, &[]);
        let mut rows = crate::spill::Stash::new();
        for r in crate::exec::matching(&old, &crate::plan::Access::Full, None, &ctx)? {
            let (key, mut row) = r?;
            let pk = &key[INDEX_PREFIX_LEN..];
            row[column] = match ctx.txn.get(&shadow_key(table_id, column, pk))? {
                Some(b) if !b.is_empty() => {
                    let v: Vec<f32> = b
                        .as_chunks::<4>()
                        .0
                        .iter()
                        .map(|c| f32::from_le_bytes(*c))
                        .collect();
                    crate::dml::assign(ctx.txn, crate::vectors::checked(&v)?, &new, column)?
                }
                _ => Value::Null,
            };
            rows.push(crate::exec::keyed(key, row))?;
        }
        rows.seal()?
    };
    crate::dml::replace_rows(txn.as_mut(), reg, &new, rows)?;
    // The old model's jobs are moot: a changed text's vector is made.
    delete_prefix(txn.as_mut(), &slot_prefix(table_id, column))?;
    delete_prefix(txn.as_mut(), &shadow_prefix(table_id, column))?;
    catalog::update_table(txn.as_mut(), &new)?;
    match txn.commit() {
        Ok(_) => Ok(true),
        Err(nucleus_kv::Error::Conflict { .. }) => Ok(false),
        Err(e) => Err(e.into()),
    }
}

/// The vectors of `texts` by model `model`, a result a text: the batch's,
/// or — refused as a whole, by an error that will not pass — each text's
/// own.
fn call(txn: &dyn KvTxn, model: &str, texts: &[&str]) -> Vec<Result<Arc<[f32]>>> {
    if texts.is_empty() {
        return Vec::new();
    }
    match crate::models::embed_unchecked(txn, model, texts, crate::models::Input::Document, false) {
        Ok(v) => v.into_iter().map(Ok).collect(),
        Err(e) if transient(&e) || texts.len() == 1 => {
            texts.iter().map(|_| Err(e.clone())).collect()
        }
        Err(_) => texts
            .iter()
            .map(|t| {
                crate::models::embed_unchecked(
                    txn,
                    model,
                    &[t],
                    crate::models::Input::Document,
                    false,
                )
                .map(|mut v| v.remove(0))
            })
            .collect(),
    }
}

/// Writes a group's outcomes: vectors to rows whose text is still the one
/// embedded, failures to their jobs — each job only as it was read (one
/// written since is its row's newer job).
#[allow(clippy::too_many_arguments)]
fn write_back(
    kv: &Arc<dyn Kv>,
    reg: &Registry,
    t: &Table,
    slot: usize,
    jobs: &[Job],
    texts: &[Option<String>],
    results: Vec<Result<Arc<[f32]>>>,
    now: i64,
    round: &mut Round,
) -> Result<()> {
    let (column, shadow) = (slot & !NEXT, slot & NEXT != 0);
    let mut txn = kv.begin(TxnOptions::default())?;
    let w = crate::dml::Writer::new(&*txn, reg, t.clone())?;
    let mut changes = Vec::new();
    let mut deletes = Vec::new();
    let mut puts = Vec::new();
    {
        let source = bind_source(&*txn, reg, t, column)?;
        let ctx = Ctx::new(&*txn, reg, &[]);
        let mut labels = crate::enums::Labels::default();
        let mut results = results.into_iter();
        for (j, text) in jobs.iter().zip(texts) {
            let result = text
                .as_ref()
                .map(|_| results.next().expect("a result a text"));
            if txn.get(&j.key)?.as_deref() != Some(&j.entry[..]) {
                continue;
            }
            let key = row_key(t, &j.pk);
            let Some(row) = w.storage.get(&*txn, t, &key, None, &mut labels)? else {
                deletes.push(j.key.clone());
                round.cleared += 1;
                continue;
            };
            if text_of(&source, &row, &ctx)? != *text {
                continue;
            }
            let failure = match result {
                // A next model's: beside the column, until it takes them.
                None if shadow => {
                    puts.push((shadow_key(t.id, column, &j.pk), Vec::new()));
                    deletes.push(j.key.clone());
                    round.cleared += 1;
                    None
                }
                Some(Ok(v)) if shadow => match crate::vectors::checked(&v) {
                    Ok(_) => {
                        let bytes = v.iter().flat_map(|c| c.to_le_bytes()).collect();
                        puts.push((shadow_key(t.id, column, &j.pk), bytes));
                        deletes.push(j.key.clone());
                        round.embedded += 1;
                        None
                    }
                    Err(e) => Some(e),
                },
                None => {
                    if !row[column].is_null() {
                        let mut new = row.clone();
                        new[column] = Value::Null;
                        changes.push((key, row, new));
                    }
                    deletes.push(j.key.clone());
                    round.cleared += 1;
                    None
                }
                Some(Ok(v)) => {
                    match crate::vectors::checked(&v)
                        .and_then(|v| crate::dml::assign(&*txn, v, t, column))
                    {
                        Ok(v) => {
                            let mut new = row.clone();
                            new[column] = v;
                            changes.push((key, row, new));
                            deletes.push(j.key.clone());
                            round.embedded += 1;
                            None
                        }
                        Err(e) => Some(e),
                    }
                }
                Some(Err(e)) => Some(e),
            };
            if let Some(e) = failure {
                let mut entry = Entry::decode(&j.entry)?;
                entry.attempts += 1;
                entry.error = Some(format!("{} ({})", e.message, e.code));
                if transient(&e) {
                    let wait = match crate::models::retry_after(&e) {
                        Some(d) => d.as_micros() as i64,
                        None => backoff(kv.as_ref(), entry.attempts),
                    };
                    entry.next_at = now + wait;
                } else {
                    entry.failed = true;
                    entry.next_at = now + FAILED_RETRY_MS * 1_000;
                }
                round.next = Some(round.next.map_or(entry.next_at, |n| n.min(entry.next_at)));
                puts.push((j.key.clone(), entry.encode()));
            }
        }
    }
    for k in &deletes {
        txn.delete(k)?;
    }
    for (k, v) in &puts {
        txn.put(k, v)?;
    }
    if !changes.is_empty() {
        crate::dml::update_rows(txn.as_mut(), reg, &w, &changes)?;
    }
    match txn.commit() {
        Ok(_) => Ok(()),
        // A writer got there first: its jobs are the next round's.
        Err(nucleus_kv::Error::Conflict { .. }) => Ok(()),
        Err(e) => Err(e.into()),
    }
}

// ------------------------------------------------------------ drivers

/// After a statement of a session on database `kv`: a round, when no
/// background worker serves it and a job may be due — so the embedded
/// library, without a thread of its own, keeps its columns current with
/// the work of its statements.
pub fn after_statement(kv: &Arc<dyn Kv>, reg: &Registry) -> Result<()> {
    let now = crate::datetime::from_system(kv.wall_clock());
    let go = with_driver(kv.instance(), |d| {
        let go = !d.background && !d.busy && (d.maybe || d.next.is_some_and(|n| n <= now));
        if go {
            d.maybe = false;
        }
        go
    });
    if go {
        work(kv, reg)?;
    }
    Ok(())
}

/// Rounds for database `kv` are the caller's from now on: its sessions
/// leave them (a host running [`work`] on its own schedule, as [`serve`]
/// does).
pub fn rounds_by_caller(kv: &dyn Kv) {
    with_driver(kv.instance(), |d| d.background = true);
}

/// Starts a background worker for database `kv`: rounds while jobs are
/// due, else asleep until one is put or will be due (the server's; the
/// sessions then leave the rounds to it).
pub fn serve(kv: Arc<dyn Kv>, reg: Arc<Registry>) -> std::thread::JoinHandle<()> {
    let instance = kv.instance();
    rounds_by_caller(kv.as_ref());
    std::thread::spawn(move || {
        loop {
            match work(&kv, &reg) {
                Ok(r) if r.due > 0 || r.worked() => continue,
                Ok(_) => {}
                Err(e) => eprintln!("nucleus: embedding columns: {}", e.message),
            }
            let (lock, cv) = drivers();
            let mut d = lock.lock().unwrap_or_else(|e| e.into_inner());
            let now = crate::datetime::from_system(kv.wall_clock());
            let dr = d.entry(instance).or_default();
            if dr.maybe {
                dr.maybe = false;
                continue;
            }
            let wait = dr.next.map_or(Duration::from_secs(60), |n| {
                Duration::from_micros((n - now).clamp(1_000, 60_000_000) as u64)
            });
            let (mut d, _) = cv.wait_timeout(d, wait).unwrap_or_else(|e| e.into_inner());
            d.entry(instance).or_default().maybe = false;
        }
    })
}

/// `embedding.pending = wait`: rounds until no job is left but those
/// failed for good, waiting for jobs being retried — an error
/// (`57014`) if one will not be tried before `deadline` (µs since 2000;
/// a minute from now without one).
pub fn drain(kv: &Arc<dyn Kv>, reg: &Registry, deadline: Option<i64>) -> Result<()> {
    let start = crate::datetime::from_system(kv.wall_clock());
    let deadline = deadline.unwrap_or(start + 60_000_000);
    loop {
        let r = work(kv, reg)?;
        let now = crate::datetime::from_system(kv.wall_clock());
        if r.busy {
            if now > deadline {
                return Err(still_pending(None));
            }
            kv.sleep(Duration::from_millis(5));
            continue;
        }
        // A column's next model's jobs are not waited for.
        if r.waiting == 0 {
            return Ok(());
        }
        if r.worked() || r.due > 0 {
            continue;
        }
        let next = r.next.unwrap_or(now);
        if next > deadline {
            return Err(still_pending(Some(r.waiting)));
        }
        kv.sleep(Duration::from_micros((next - now).max(1_000) as u64));
    }
}

fn still_pending(n: Option<usize>) -> Error {
    Error::query_canceled(format!(
        "canceling statement: {} still pending past the statement's time (embedding.pending = wait; nc_catalog.embedding_jobs shows them)",
        n.map_or("embedding jobs".to_string(), |n| format!(
            "{n} embedding jobs"
        ))
    ))
}

// ------------------------------------------------------------ catalog

/// A job, as `nc_catalog.embedding_jobs` shows it.
pub struct JobRow {
    /// The table.
    pub table: String,
    /// The column.
    pub column: String,
    /// The model.
    pub model: String,
    /// A job for the column's next model (`ALTER COLUMN … SET MODEL`).
    pub next: bool,
    /// The row's primary key, as text.
    pub key: String,
    /// `pending`, `retrying` or `failed`.
    pub state: &'static str,
    /// Failed calls.
    pub attempts: u32,
    /// When it was put (µs since 2000).
    pub enqueued: i64,
    /// Not before (µs since 2000; `None`: at once).
    pub next_attempt: Option<i64>,
    /// The last error.
    pub error: Option<String>,
}

/// The queued jobs, of the tables `visible` lets through.
pub fn jobs(txn: &dyn KvTxn, visible: &dyn Fn(&Table) -> bool) -> Result<Vec<JobRow>> {
    let tables: HashMap<u32, Table> = catalog::tables(txn)?
        .into_iter()
        .map(|t| (t.id, t))
        .collect();
    let end = nucleus_kv::prefix_end(&QUEUE).expect("queue prefix");
    let mut out = Vec::new();
    for e in txn.scan(Bound::Included(&QUEUE[..]), Bound::Excluded(&end[..]))? {
        let (k, v) = e?;
        let Some((table_id, slot, pk)) = parse_key(&k) else {
            continue;
        };
        let (column, next) = (slot & !NEXT, slot & NEXT != 0);
        let Some(t) = tables.get(&table_id).filter(|t| visible(t)) else {
            continue;
        };
        let Some(col) = t.columns.get(column) else {
            continue;
        };
        let entry = Entry::decode(&v)?;
        let key = match crate::encoding::decode_key(pk, t.primary_key.len()) {
            Ok((vals, _)) => vals
                .iter()
                .map(|v| v.to_string())
                .collect::<Vec<_>>()
                .join(", "),
            Err(_) => pk.iter().map(|b| format!("{b:02x}")).collect(),
        };
        out.push(JobRow {
            table: t.name.clone(),
            column: col.name.clone(),
            model: col
                .generated
                .as_ref()
                .and_then(|g| if next { g.next_model() } else { g.model() })
                .unwrap_or("")
                .to_string(),
            next,
            key,
            state: if entry.failed {
                "failed"
            } else if entry.attempts > 0 {
                "retrying"
            } else {
                "pending"
            },
            attempts: entry.attempts,
            enqueued: entry.enqueued,
            next_attempt: (entry.next_at > 0).then_some(entry.next_at),
            error: entry.error,
        });
    }
    Ok(out)
}
